export PATH="$HOME/.local/bin:$PATH"; cd /workspace/repo; cd /workspace/repo && python3 - <<'EOF'
from pathlib import Path
p = Path("apps/factory/app/components/ProposalFeedback.vue")
t = p.read_text()

old_import = """import {
  clearFeedbackEntry,
  feedbackChangedEvent,
  feedbackKeyFor,
  loadFeedback,
  setFeedbackEntry,
  storeFeedback,
  type FeedbackVerdict,
  type ProposalFeedbackMap,
} from "../utils/proposal-feedback";"""
new_import = """import {
  clearFeedbackEntry,
  feedbackChangedEvent,
  feedbackKeyFor,
  loadFeedback,
  setFeedbackEntry,
  storeFeedback,
  storageProblemFor,
  type FeedbackStorageProblem,
  type FeedbackVerdict,
  type ProposalFeedbackMap,
} from "../utils/proposal-feedback";"""
assert old_import in t
t = t.replace(old_import, new_import)

old_ref = 'const storageProblem = ref<"malformed" | "unavailable" | "">("");'
new_ref = 'const storageProblem = ref<FeedbackStorageProblem>("");'
assert old_ref in t
t = t.replace(old_ref, new_ref)

old_refresh = """function refresh() {
  try {
    const loaded = loadFeedback(localStorage);
    entries.value = loaded.entries;
    if (loaded.unavailable) storageProblem.value = "unavailable";
    else if (loaded.malformed) storageProblem.value = "malformed";
  } catch {
    storageProblem.value = "unavailable";
  }
}"""
new_refresh = """function refresh() {
  try {
    const loaded = loadFeedback(localStorage);
    entries.value = loaded.entries;
    // A clean load proves storage recovered, so a previous warning clears
    // instead of lingering after the failure is gone.
    storageProblem.value = storageProblemFor(loaded);
  } catch {
    storageProblem.value = "unavailable";
  }
}"""
assert old_refresh in t
t = t.replace(old_refresh, new_refresh)

old_persist = """    const result = storeFeedback(localStorage, next);
    saveProblem.value = result.unavailable;
    if (!result.unavailable) {
      entries.value = next;
      window.dispatchEvent(new CustomEvent(feedbackChangedEvent));
    }"""
new_persist = """    const result = storeFeedback(localStorage, next);
    saveProblem.value = result.unavailable;
    if (!result.unavailable) {
      entries.value = next;
      // A successful save proves storage works, so it also clears a stale
      // malformed/unavailable warning (the save overwrote the bad entry).
      storageProblem.value = "";
      window.dispatchEvent(new CustomEvent(feedbackChangedEvent));
    }"""
assert old_persist in t
t = t.replace(old_persist, new_persist)

old_update = """  try {
    const loaded = loadFeedback(localStorage);
    persist(transform(loaded.entries));
  } catch {"""
new_update = """  try {
    const loaded = loadFeedback(localStorage);
    storageProblem.value = storageProblemFor(loaded);
    persist(transform(loaded.entries));
  } catch {"""
assert old_update in t
t = t.replace(old_update, new_update)

p.write_text(t)
print("component patched")
EOF

export PATH="$HOME/.local/bin:$PATH"; cd /workspace/repo; cd /workspace/repo && python3 - <<'EOF'
from pathlib import Path
p = Path("apps/factory/tests/proposal-feedback.test.ts")
t = p.read_text()

old_import = """import {
  clearFeedbackEntry,
  feedbackKeyFor,
  loadFeedback,
  readFeedbackMap,
  setFeedbackEntry,
  storeFeedback,
  proposalFeedbackStorageKey,
} from "../app/utils/proposal-feedback.ts";"""
new_import = """import {
  clearFeedbackEntry,
  feedbackKeyFor,
  loadFeedback,
  readFeedbackMap,
  setFeedbackEntry,
  storeFeedback,
  storageProblemFor,
  proposalFeedbackStorageKey,
} from "../app/utils/proposal-feedback.ts";"""
assert old_import in t
t = t.replace(old_import, new_import)

t += """
test("storage warnings map cleanly from load results so recovery clears them", () => {
  assert.equal(storageProblemFor({ malformed: true, unavailable: false }), "malformed");
  assert.equal(storageProblemFor({ malformed: false, unavailable: true }), "unavailable");
  // Error-to-success: a clean load after either failure clears the warning.
  assert.equal(storageProblemFor({ malformed: false, unavailable: false }), "");
});

test("malformed storage recovers through a successful save that overwrites the bad entry", () => {
  let raw: string | null = "{not-json";
  const storage = {
    getItem: (_key: string) => raw,
    setItem: (_key: string, value: string) => { raw = value; },
  };
  const before = loadFeedback(storage);
  assert.equal(before.malformed, true);
  assert.equal(storageProblemFor(before), "malformed");
  const entries = setFeedbackEntry(before.entries, "wrun_a:proposal:1", verdict);
  assert.equal(storeFeedback(storage, entries).unavailable, false);
  const after = loadFeedback(storage);
  assert.equal(after.malformed, false);
  assert.equal(after.unavailable, false);
  assert.equal(storageProblemFor(after), "");
  assert.equal(after.entries["wrun_a:proposal:1"]?.verdict, "useful");
});

test("unavailable storage warning clears after a later load succeeds", () => {
  let broken = true;
  const store = new Map<string, string>();
  const storage = {
    getItem: (key: string) => {
      if (broken) throw new Error("denied");
      return store.get(key) ?? null;
    },
    setItem: (key: string, value: string) => { store.set(key, value); },
  };
  const before = loadFeedback(storage);
  assert.equal(before.unavailable, true);
  assert.equal(storageProblemFor(before), "unavailable");
  broken = false;
  const after = loadFeedback(storage);
  assert.equal(after.unavailable, false);
  assert.equal(storageProblemFor(after), "");
});
"""
p.write_text(t)
print("tests patched")
EOF
node --test apps/factory/tests/proposal-feedback.test.ts 2>&1 | tail -15

