export PATH="$HOME/.local/bin:$PATH"; cd /workspace/repo; cd /workspace/repo && python3 - <<'EOF'
from pathlib import Path
p = Path("apps/factory/app/components/ProposalFeedback.vue")
t = p.read_text()

old_refresh = """function refresh() {
  try {
    const loaded = loadFeedback(localStorage);
    entries.value = loaded.entries;
    // A clean load proves storage recovered, so a previous warning clears
    // instead of lingering after the failure is gone.
    storageProblem.value = storageProblemFor(loaded);
  } catch {
    storageProblem.value = "unavailable";
  }
}"""
new_refresh = """function refresh() {
  try {
    const loaded = loadFeedback(localStorage);
    // Keep the last known marks when storage cannot be read, so a failure
    // after a success still shows the selected verdict alongside the warning.
    if (!loaded.unavailable) entries.value = loaded.entries;
    // A clean load proves storage recovered, so a previous warning clears
    // instead of lingering after the failure is gone.
    storageProblem.value = storageProblemFor(loaded);
  } catch {
    storageProblem.value = "unavailable";
  }
}"""
assert old_refresh in t
t = t.replace(old_refresh, new_refresh)

old_update = """  try {
    const loaded = loadFeedback(localStorage);
    storageProblem.value = storageProblemFor(loaded);
    persist(transform(loaded.entries));
  } catch {"""
new_update = """  try {
    const loaded = loadFeedback(localStorage);
    storageProblem.value = storageProblemFor(loaded);
    // Build on the last known in-memory marks when the re-read fails, so a
    // transient read failure cannot wipe this or sibling verdicts on save.
    persist(transform(loaded.unavailable ? entries.value : loaded.entries));
  } catch {"""
assert old_update in t
t = t.replace(old_update, new_update)

p.write_text(t)
print("component patched")
EOF

export PATH="$HOME/.local/bin:$PATH"; cd /workspace/repo; cd /workspace/repo && python3 - <<'EOF'
from pathlib import Path
p = Path("apps/factory/tests/proposal-feedback.test.ts")
t = p.read_text()
t += """
test("a storage failure after a success shows a problem again without losing verdicts", () => {
  let broken = false;
  const store = new Map<string, string>();
  const storage = {
    getItem: (key: string) => {
      if (broken) throw new Error("denied");
      return store.get(key) ?? null;
    },
    setItem: (key: string, value: string) => { store.set(key, value); },
  };
  // Success first: verdict and reason round-trip through storage.
  const saved = setFeedbackEntry({}, "wrun_a:proposal:1", verdict);
  assert.equal(storeFeedback(storage, saved).unavailable, false);
  let loaded = loadFeedback(storage);
  assert.equal(storageProblemFor(loaded), "");
  assert.equal(loaded.entries["wrun_a:proposal:1"]?.reason, "It names the gap");
  // Later failure: the loader reports a truthful problem again, and the
  // previously saved entry survives (component keeps last-known marks).
  broken = true;
  loaded = loadFeedback(storage);
  assert.equal(storageProblemFor(loaded), "unavailable");
  assert.equal(loaded.entries["wrun_a:proposal:1"], undefined);
  assert.equal(saved["wrun_a:proposal:1"]?.verdict, "useful");
  assert.equal(saved["wrun_a:proposal:1"]?.reason, "It names the gap");
  // A failed save reports unavailability without clobbering stored marks.
  const failedSave = storeFeedback(
    { getItem: storage.getItem, setItem: () => { throw new Error("denied"); } },
    setFeedbackEntry(saved, "wrun_a:proposal:2", { verdict: "not-useful", reason: "Too broad" }),
  );
  assert.equal(failedSave.unavailable, true);
  broken = false;
  const recovered = loadFeedback(storage);
  assert.equal(storageProblemFor(recovered), "");
  assert.equal(recovered.entries["wrun_a:proposal:1"]?.verdict, "useful");
  assert.equal(recovered.entries["wrun_a:proposal:1"]?.reason, "It names the gap");
});
"""
p.write_text(t)
print("tests patched")
EOF
export PATH="$HOME/.local/bin:$PATH" && node --test apps/factory/tests/proposal-feedback.test.ts 2>&1 | tail -16

